// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 650, 900);

var state = { A0: 1, view: 'Concentration', t: 0, step: 0 };
var tMax = 10, tEq = 5.5;
var graph = { x0: 83, y0: 775, w: 525, h: 250 };
var draggingMarker = false;

var red = '#c44a2a';
var blue = '#516dae';
var gray = '#7f7f7f';
var paleYellow = '#f7edc9';

var defs = draw.defs();
var redGrad = defs.gradient('radial', function (add) {
  add.stop(0, '#ff9a9a');
  add.stop(0.45, '#f21f2d');
  add.stop(1, '#aa111a');
});
var blueGrad = defs.gradient('radial', function (add) {
  add.stop(0, '#9fc2ff');
  add.stop(0.45, '#557ac4');
  add.stop(1, '#263f83');
});

var steps = [
  {
    title: 'Start with N₂O₄',
    narration: 'At t = 0, the container begins with mostly colorless N2O4, so [N2O4] is high, [NO2] is very low, the forward rate is large, and the reverse rate is nearly zero.',
    state: { initialN2O4: 1, graphView: 'Concentration', time: 0 }
  },
  {
    title: 'Watch concentrations change',
    narration: 'Drag the time marker to the pre-equilibrium region: N2O4 decomposes into brown NO2, so the red NO2 concentration curve rises while the blue N2O4 curve falls.',
    state: { initialN2O4: 1, graphView: 'Concentration', time: 3.0 }
  },
  {
    title: 'Compare the rates',
    narration: 'Switch to the rate graph at the same time marker position: the forward rate is falling as N2O4 is used up, while the reverse rate is rising as NO2 accumulates.',
    state: { initialN2O4: 1, graphView: 'Rate', time: 3.0 }
  },
  {
    title: 'Reach dynamic equilibrium',
    narration: 'At the dashed boundary, the two rate curves meet and remain equal. The concentrations become constant, but the equal forward and reverse reactions continue.',
    state: { initialN2O4: 1, graphView: 'Rate', time: tEq }
  },
  {
    title: 'Change the starting amount',
    narration: 'Move the initial N2O4 slider: the vial color, molecule counts, concentration plateaus, and rate curves all update together, but the defining condition for equilibrium remains equality of opposing rates.',
    state: { initialN2O4: 1.6, graphView: 'Concentration', time: 7.2 }
  }
];

function progressAt(t) {
  if (t >= tEq) return 1;
  var tau = 1.55;
  return (1 - Math.exp(-t / tau)) / (1 - Math.exp(-tEq / tau));
}

function valuesAt(t) {
  var p = progressAt(Math.max(0, Math.min(tMax, t)));
  var A0 = state.A0;
  var aEq = 0.38 * A0;
  var bStart = 0.02 * A0;
  var bEq = 1.23 * A0;
  var n2o4 = A0 + (aEq - A0) * p;
  var no2 = bStart + (bEq - bStart) * p;
  var rEq = 0.46 * Math.pow(A0, 0.78);
  var rf0 = 0.92 * Math.pow(A0, 0.78);
  var forward = rEq + (rf0 - rEq) * Math.pow(1 - p, 1.15);
  var reverse = rEq * Math.pow(p, 1.08);
  if (p >= 1) { forward = rEq; reverse = rEq; }
  return { p: p, n2o4: n2o4, no2: no2, forward: forward, reverse: reverse, aEq: aEq, bEq: bEq, rEq: rEq };
}

function tToScreen(t) {
  return graph.x0 + (t / tMax) * graph.w;
}

function valToScreen(v, maxVal) {
  return graph.y0 - (v / maxVal) * graph.h;
}

function curvePoints(fn, maxVal) {
  var pts = [];
  for (var i = 0; i <= 130; i++) {
    var tt = tMax * i / 130;
    var vv = fn(tt);
    pts.push([tToScreen(tt), valToScreen(vv, maxVal)]);
  }
  return pts.map(function (p) { return p[0].toFixed(1) + ',' + p[1].toFixed(1); }).join(' ');
}

function addHaloText(parent, txt, x, y, size, opts) {
  opts = opts || {};
  return parent.text(txt)
    .font({ family: 'Arial, sans-serif', size: size, anchor: opts.anchor || 'middle', weight: opts.weight || 'normal' })
    .fill(opts.fill || '#000')
    .move(x, y)
    .attr({ 'paint-order': 'stroke', stroke: opts.halo || '#fff', 'stroke-width': opts.strokeWidth || 4, 'stroke-linejoin': 'round' });
}

function drawSphere(parent, x, y, r, fill, stroke) {
  parent.circle(2 * r).center(x, y).fill(fill).stroke({ color: stroke || '#777', width: 0.5, opacity: 0.55 });
  parent.circle(r * 0.55).center(x - r * 0.32, y - r * 0.35).fill('#fff').opacity(0.28);
}

function drawNO2(parent, x, y, s, rot) {
  var g = parent.group();
  var a1 = rot || -0.65, a2 = a1 + 2.25;
  var ox1 = x + Math.cos(a1) * 13 * s, oy1 = y + Math.sin(a1) * 13 * s;
  var ox2 = x + Math.cos(a2) * 13 * s, oy2 = y + Math.sin(a2) * 13 * s;
  g.line(x, y, ox1, oy1).stroke({ color: '#777', width: 2 * s, opacity: 0.55 });
  g.line(x, y, ox2, oy2).stroke({ color: '#777', width: 2 * s, opacity: 0.55 });
  drawSphere(g, ox1, oy1, 7.2 * s, redGrad, '#9b1118');
  drawSphere(g, ox2, oy2, 7.2 * s, redGrad, '#9b1118');
  drawSphere(g, x, y, 6.5 * s, blueGrad, '#263f83');
  return g;
}

function drawN2O4(parent, x, y, s, rot) {
  var g = parent.group();
  var dx = Math.cos(rot || 0.25) * 9.5 * s, dy = Math.sin(rot || 0.25) * 9.5 * s;
  g.line(x - dx, y - dy, x + dx, y + dy).stroke({ color: '#666', width: 2.2 * s, opacity: 0.65 });
  drawNO2(g, x - dx, y - dy, s * 0.9, (rot || 0.25) + 2.4);
  drawNO2(g, x + dx, y + dy, s * 0.9, (rot || 0.25) - 0.7);
  return g;
}

function drawTestTube(parent, cx, cy, color, angle) {
  var g = parent.group();
  g.transform({ rotate: angle, cx: cx, cy: cy });
  g.line(cx, cy - 68, cx, cy + 26).stroke({ color: '#aab0c8', width: 26, linecap: 'round', opacity: 0.33 });
  g.line(cx, cy - 62, cx, cy + 22).stroke({ color: color, width: 19, linecap: 'round', opacity: 0.78 });
  g.line(cx - 9, cy - 58, cx - 9, cy + 8).stroke({ color: '#fff', width: 3.3, linecap: 'round', opacity: 0.42 });
  g.line(cx, cy - 68, cx, cy + 28).stroke({ color: '#7d85a8', width: 1.2, linecap: 'round', opacity: 0.42 });
  return g;
}

function drawCurvedArrow(parent, x1, y1, x2, y2, bend) {
  var c1x = x1 + bend, c1y = y1 + 38;
  var c2x = x2 - bend * 0.35, c2y = y2 - 55;
  parent.path('M' + x1 + ' ' + y1 + ' C ' + c1x + ' ' + c1y + ', ' + c2x + ' ' + c2y + ', ' + x2 + ' ' + y2)
    .fill('none').stroke({ color: '#111', width: 1.2 });
  parent.polygon([[x2 - 22, y2 - 34], [x2 + 22, y2 - 34], [x2, y2 + 4]])
    .fill('#f8f8f8').stroke({ color: '#111', width: 1.1 });
}

var molLayouts = {
  leftA: [[58,320,.95,-.2],[104,310,1.0,.6],[151,323,.9,-.7],[70,368,.95,.2],[107,388,.95,-.4],[148,366,.9,.8]],
  leftB: [[100,348,.95,.1]],
  midA: [[268,315,.75,.1],[339,314,.75,.9],[281,366,.72,-.7],[380,363,.7,.2]],
  midB: [[300,342,.9,1.1],[356,341,.9,-.5],[250,355,.85,.3],[406,335,.85,1.8],[322,385,.85,-.8]],
  rightA: [[496,318,.7,.4],[562,319,.7,-.8],[507,371,.68,.2],[548,377,.68,-.4]],
  rightB: [[473,349,.82,-.4],[525,345,.82,1.2],[584,349,.82,.1],[492,386,.8,.7],[576,389,.8,-.8],[535,358,.82,-.2]]
};

function drawContainer(parent, cx, cy, label, tubeColor, snap, highlight) {
  var g = parent.group();
  addHaloText(g, label, cx, 36, 24, { anchor: 'middle' });
  drawTestTube(g, cx - 2, 130, tubeColor, -32);
  drawCurvedArrow(g, cx + 18, 176, cx, 240, cx < 200 ? -35 : -28);
  var ring = g.circle(150).center(cx, cy).fill('#f7f7f7').stroke({ color: highlight ? '#d29a21' : gray, width: highlight ? 5 : 4 });
  ring.on('mousemove', function (e) { showTooltip(label + ': a sealed sample of N₂O₄/NO₂ at this stage.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup(label, 'The particles keep reacting in both directions. At equilibrium the visible mixture stays constant because the two opposing reaction rates match.');
    }).css('cursor', 'pointer');

  var scale = Math.max(0.55, Math.min(1.35, Math.sqrt(state.A0)));
  molLayouts[snap + 'A'].forEach(function (m) { drawN2O4(g, m[0], m[1], m[2] * scale, m[3]); });
  molLayouts[snap + 'B'].forEach(function (m) { drawNO2(g, m[0], m[1], m[2] * scale, m[3]); });

  return g;
}

function drawTopPanel() {
  var top = draw.group();
  addHaloText(top, 'N₂O₄(g) ⇌ 2NO₂(g)', 325, 4, 22, { weight: 'normal' });
  var current = state.t < 1.4 ? 'left' : (state.t < tEq ? 'mid' : 'right');
  drawContainer(top, 110, 315, 't = 0', '#d7dbf2', 'left', current === 'left');
  drawContainer(top, 325, 315, 'pre-equilibrium', '#f0cf52', 'mid', current === 'mid');
  drawContainer(top, 540, 315, 'at equilibrium', '#df7a2e', 'right', current === 'right');

  top.line(127, 382, 180, 415).stroke({ color: '#111', width: 4 });
  addHaloText(top, 'N₂O₄', 183, 400, 24, { anchor: 'start' });
  top.line(315, 375, 370, 414).stroke({ color: '#111', width: 4 });
  addHaloText(top, 'NO₂', 374, 400, 24, { anchor: 'start' });
  addHaloText(top, '(a)', 325, 445, 24, {});
}

function drawAxes(g, ylabel, panelLabel) {
  g.rect(graph.w * (tMax - tEq) / tMax, graph.h)
    .move(tToScreen(tEq), graph.y0 - graph.h)
    .fill(paleYellow).opacity(0.85);
  g.line(tToScreen(tEq), graph.y0 - graph.h, tToScreen(tEq), graph.y0)
    .stroke({ color: '#111', width: 1.6, dasharray: '9 8' });

  g.line(graph.x0, graph.y0, graph.x0, graph.y0 - graph.h - 20).stroke({ color: '#111', width: 2 });
  g.polygon([[graph.x0 - 7, graph.y0 - graph.h - 20], [graph.x0 + 7, graph.y0 - graph.h - 20], [graph.x0, graph.y0 - graph.h - 42]]).fill('#111');
  g.line(graph.x0, graph.y0, graph.x0 + graph.w + 18, graph.y0).stroke({ color: '#111', width: 2 });
  g.polygon([[graph.x0 + graph.w + 18, graph.y0 - 7], [graph.x0 + graph.w + 18, graph.y0 + 7], [graph.x0 + graph.w + 39, graph.y0]]).fill('#111');

  g.line(graph.x0 + 24, graph.y0, graph.x0 + 24, graph.y0 + 20).stroke({ color: '#111', width: 2 });
  addHaloText(g, '0', graph.x0 + 24, graph.y0 + 24, 21, {});
  addHaloText(g, 'Time', graph.x0 + graph.w / 2, graph.y0 + 43, 23, {});
  addHaloText(g, ylabel, graph.x0 - 48, graph.y0 - graph.h / 2 - 20, 23, {}).transform({ rotate: -90, cx: graph.x0 - 48, cy: graph.y0 - graph.h / 2 });
  addHaloText(g, 'Equilibrium\nachieved', tToScreen(7.8), graph.y0 - graph.h * 0.63, 24, {});
  addHaloText(g, panelLabel, 325, graph.y0 + 87, 24, {});
}

function drawGraph() {
  var g = draw.group();
  var maxConc = 2.55;
  var maxRate = 1.65;

  if (state.view === 'Concentration') {
    drawAxes(g, 'Concentration', '(b)');
    var blueLine = g.polyline(curvePoints(function (tt) { return valuesAt(tt).n2o4; }, maxConc))
      .fill('none').stroke({ color: blue, width: 5, linecap: 'round', linejoin: 'round' });
    var redLine = g.polyline(curvePoints(function (tt) { return valuesAt(tt).no2; }, maxConc))
      .fill('none').stroke({ color: red, width: 5, linecap: 'round', linejoin: 'round' });
    redLine.on('mousemove', function (e) { showTooltip('[NO₂] rises, then becomes constant after equilibrium begins.', e); }).on('mouseleave', hideTooltip).css('cursor', 'pointer');
    blueLine.on('mousemove', function (e) { showTooltip('[N₂O₄] falls, then becomes constant after equilibrium begins.', e); }).on('mouseleave', hideTooltip).css('cursor', 'pointer');
    addHaloText(g, 'NO₂', graph.x0 + 174, graph.y0 - 188, 22, {});
    addHaloText(g, 'N₂O₄', graph.x0 + 173, graph.y0 - 92, 22, {});
  } else {
    drawAxes(g, 'Rate', '(c)');
    var fLine = g.polyline(curvePoints(function (tt) { return valuesAt(tt).forward; }, maxRate))
      .fill('none').stroke({ color: blue, width: 5, linecap: 'round', linejoin: 'round' });
    var rLine = g.polyline(curvePoints(function (tt) { return valuesAt(tt).reverse; }, maxRate))
      .fill('none').stroke({ color: red, width: 5, linecap: 'round', linejoin: 'round' });
    fLine.on('mousemove', function (e) { showTooltip('Forward rate kf[N₂O₄] decreases as N₂O₄ is consumed.', e); }).on('mouseleave', hideTooltip).css('cursor', 'pointer');
    rLine.on('mousemove', function (e) { showTooltip('Reverse rate kr[NO₂]² increases as NO₂ accumulates.', e); }).on('mouseleave', hideTooltip).css('cursor', 'pointer');
    addHaloText(g, 'kᶠ[N₂O₄]', graph.x0 + 70, graph.y0 - 213, 21, { anchor: 'start' });
    addHaloText(g, 'kʳ[NO₂]²', graph.x0 + 70, graph.y0 - 98, 21, { anchor: 'start' });
  }

  var markerX = tToScreen(state.t);
  var marker = g.group();
  marker.line(markerX, graph.y0 - graph.h - 12, markerX, graph.y0 + 8)
    .stroke({ color: '#111', width: 2.2, dasharray: state.t >= tEq - 0.02 ? 'none' : '5 5' });
  marker.circle(14).center(markerX, graph.y0 - graph.h - 13).fill('#fff').stroke({ color: '#111', width: 2 });
  marker.rect(34, graph.h + 44).move(markerX - 17, graph.y0 - graph.h - 34).fill('#000').opacity(0.001);
  marker.on('mousedown', function (e) { draggingMarker = true; updateTimeFromEvent(e); e.preventDefault(); })
    .on('mousemove', function (e) { showTooltip('Drag to sample the same system at another time.', e); })
    .on('mouseleave', hideTooltip)
    .css('cursor', 'ew-resize');

  var vals = valuesAt(state.t);
  var boxX = markerX < graph.x0 + graph.w * 0.63 ? markerX + 13 : markerX - 185;
  var boxY = graph.y0 - graph.h - 5;
  g.rect(172, 104).move(boxX, boxY).rx(7).fill('#fff').opacity(0.92).stroke({ color: '#bbb', width: 1 });
  g.text('t = ' + state.t.toFixed(1) +
    '\n[N₂O₄] = ' + vals.n2o4.toFixed(2) +
    '\n[NO₂] = ' + vals.no2.toFixed(2) +
    '\nforward rate = ' + vals.forward.toFixed(2) +
    '\nreverse rate = ' + vals.reverse.toFixed(2))
    .font({ family: 'Arial, sans-serif', size: 14, anchor: 'start' })
    .fill('#111').move(boxX + 9, boxY + 8);

  var dotVal = state.view === 'Concentration' ? vals.no2 : vals.reverse;
  var dotMax = state.view === 'Concentration' ? maxConc : maxRate;
  g.circle(10).center(markerX, valToScreen(dotVal, dotMax)).fill(red).stroke({ color: '#fff', width: 2 });
}

function render() {
  draw.clear();
  draw.defs().add(redGrad);
  draw.defs().add(blueGrad);
  draw.rect(650, 900).fill('#fff');
  drawTopPanel();
  drawGraph();
}

function updateTimeFromEvent(e) {
  var rect = document.getElementById('container').getBoundingClientRect();
  var vb = draw.viewbox();
  var sx = vb.width / rect.width;
  var x = (e.clientX - rect.left) * sx + vb.x;
  var t = ((x - graph.x0) / graph.w) * tMax;
  state.t = Math.max(0, Math.min(tMax, t));
  render();
}

document.addEventListener('mousemove', function (e) {
  if (draggingMarker) updateTimeFromEvent(e);
});
document.addEventListener('mouseup', function () { draggingMarker = false; });

function update_initialN2O4(v) {
  state.A0 = v;
  render();
