  addHaloText(g, label, cx, 36, 24, { anchor: 'middle' });
  drawTestTube(g, cx - 2, 130, tubeColor, -32);
  drawCurvedArrow(g, cx + 18, 176, cx, 240, cx < 200 ? -35 : -28);
  var ring = g.circle(150).center(cx, cy).fill('#f7f7f7').stroke({ color: highlight ? '#d29a21' : gray, width: highlight ? 5 : 4 });
  ring.on('mousemove', function (e) { showTooltip(label + ': a sealed sample of N₂O₄/NO₂ at this stage.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup(label, 'The particles keep reacting in both directions. At equilibrium the visible mixture stays constant because the two opposing reaction rates match.');
    }).css('cursor', 'pointer');

  var scale = Math.max(0.55, Math.min(1.35, Math.sqrt(state.A0)));
  molLayouts[snap + 'A'].forEach(function (m) { drawN2O4(g, m[0], m[1], m[2] * scale, m[3]); });
  molLayouts[snap + 'B'].forEach(function (m) { drawNO2(g, m[0], m[1], m[2] * scale, m[3]); });

  return g;
}

