// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 650, 900);

var state = { A0: 1, view: 'Concentration', t: 0, step: 0, markerVisible: false };
var tMax = 10;
var tEq = 5.25;
var graph = { x0: 83, y0: 782, w: 525, h: 240 };
var draggingMarker = false;

var red = '#c44a2a';
var blue = '#516dae';
var gray = '#808285';
var paleYellow = '#f6edcf';

var steps = [
  {
    title: 'Start with N₂O₄',
    narration: 'At t = 0, the container begins with mostly colorless N2O4, so [N2O4] is high, [NO2] is very low, the forward rate is large, and the reverse rate is nearly zero.',
    state: { initialN2O4: 1, graphView: 'Concentration', time: 0, markerVisible: false }
  },
  {
    title: 'Watch concentrations change',
    narration: 'Drag the time marker to the pre-equilibrium region: N2O4 decomposes into brown NO2, so the red NO2 concentration curve rises while the blue N2O4 curve falls.',
    state: { initialN2O4: 1, graphView: 'Concentration', time: 3.0, markerVisible: true }
  },
  {
    title: 'Compare the rates',
    narration: 'Switch to the rate graph at the same time marker position: the forward rate is falling as N2O4 is used up, while the reverse rate is rising as NO2 accumulates.',
    state: { initialN2O4: 1, graphView: 'Rate', time: 3.0, markerVisible: true }
  },
  {
    title: 'Reach dynamic equilibrium',
    narration: 'At the dashed boundary, the two rate curves meet and remain equal. The concentrations become constant, but the equal forward and reverse reactions continue.',
    state: { initialN2O4: 1, graphView: 'Rate', time: tEq, markerVisible: true }
  },
  {
    title: 'Change the starting amount',
    narration: 'Move the initial N2O4 slider: the vial color, molecule counts, concentration plateaus, and rate curves all update together, but the defining condition for equilibrium remains equality of opposing rates.',
    state: { initialN2O4: 1.6, graphView: 'Concentration', time: 7.2, markerVisible: true }
  }
];

function progressAt(t) {
  if (t >= tEq) return 1;
  var tau = 1.55;
  return (1 - Math.exp(-t / tau)) / (1 - Math.exp(-tEq / tau));
}

function valuesAt(t) {
  var p = progressAt(Math.max(0, Math.min(tMax, t)));
  var A0 = state.A0;
  var n2o4 = A0 * (1 - 0.62 * p);
  var no2 = A0 * 1.23 * p;
  var rEq = 0.54 * Math.pow(A0, 0.78);
  var rf0 = 1.05 * Math.pow(A0, 0.78);
  var forward = rEq + (rf0 - rEq) * Math.pow(1 - p, 1.15);
  var reverse = rEq * Math.pow(p, 1.08);
  if (p >= 1) {
    forward = rEq;
    reverse = rEq;
  }
  return { p: p, n2o4: n2o4, no2: no2, forward: forward, reverse: reverse };
}

function tToScreen(t) {
  return graph.x0 + (t / tMax) * graph.w;
}

function valToScreen(v, maxVal) {
  return graph.y0 - (v / maxVal) * graph.h;
}

function curvePoints(fn, maxVal) {
  var pts = [];
  for (var i = 0; i <= 150; i++) {
    var tt = tMax * i / 150;
    var vv = fn(tt);
    pts.push(tToScreen(tt).toFixed(1) + ',' + valToScreen(vv, maxVal).toFixed(1));
  }
  return pts.join(' ');
}

function addHaloText(parent, txt, x, y, size, opts) {
  opts = opts || {};
  return parent.text(txt)
    .font({ family: 'Arial, Helvetica, sans-serif', size: size, anchor: opts.anchor || 'middle', weight: opts.weight || 'normal' })
    .fill(opts.fill || '#000')
    .move(x, y)
    .attr({ 'paint-order': 'stroke', stroke: opts.halo || '#fff', 'stroke-width': opts.strokeWidth || 4, 'stroke-linejoin': 'round' });
}

function drawSphere(parent, x, y, r, fill, stroke) {
  parent.circle(2 * r).center(x, y).fill(fill).stroke({ color: stroke || '#777', width: 0.55, opacity: 0.55 });
  parent.circle(r * 0.55).center(x - r * 0.34, y - r * 0.34).fill('#fff').opacity(0.35);
}

function drawNO2(parent, x, y, s, rot) {
  var g = parent.group();
  var a1 = rot == null ? -0.65 : rot;
  var a2 = a1 + 2.22;
  var ox1 = x + Math.cos(a1) * 12.6 * s;
  var oy1 = y + Math.sin(a1) * 12.6 * s;
  var ox2 = x + Math.cos(a2) * 12.6 * s;
  var oy2 = y + Math.sin(a2) * 12.6 * s;
  g.line(x, y, ox1, oy1).stroke({ color: '#777', width: 1.8 * s, opacity: 0.55 });
  g.line(x, y, ox2, oy2).stroke({ color: '#777', width: 1.8 * s, opacity: 0.55 });
  drawSphere(g, ox1, oy1, 7.2 * s, '#ee202b', '#9b1118');
  drawSphere(g, ox2, oy2, 7.2 * s, '#ee202b', '#9b1118');
  drawSphere(g, x, y, 6.4 * s, '#4269b1', '#263f83');
  return g;
}

function drawN2O4(parent, x, y, s, rot) {
  var g = parent.group();
  var a = rot == null ? 0.25 : rot;
  var dx = Math.cos(a) * 9.7 * s;
  var dy = Math.sin(a) * 9.7 * s;
  g.line(x - dx, y - dy, x + dx, y + dy).stroke({ color: '#666', width: 2.2 * s, opacity: 0.72 });
  drawNO2(g, x - dx, y - dy, s * 0.92, a + 2.35);
  drawNO2(g, x + dx, y + dy, s * 0.92, a - 0.72);
  return g;
}

function drawTestTube(parent, cx, cy, color, angle, opacity) {
  var g = parent.group();
  g.transform({ rotate: angle, cx: cx, cy: cy });
  g.line(cx, cy - 76, cx, cy + 26).stroke({ color: '#9ba0bd', width: 24, linecap: 'round', opacity: 0.26 });
  g.line(cx, cy - 70, cx, cy + 20).stroke({ color: color, width: 18, linecap: 'round', opacity: opacity });
  g.line(cx - 7, cy - 65, cx - 7, cy + 4).stroke({ color: '#fff', width: 3, linecap: 'round', opacity: 0.45 });
  g.line(cx, cy - 76, cx, cy + 28).stroke({ color: '#707692', width: 1.1, linecap: 'round', opacity: 0.35 });
  return g;
}

function drawCurvedArrow(parent, x1, y1, x2, y2) {
  var path = 'M' + x1 + ' ' + y1 + ' C ' + (x1 - 34) + ' ' + (y1 + 20) + ', ' + (x2 - 36) + ' ' + (y2 - 48) + ', ' + x2 + ' ' + y2;
  parent.path(path).fill('none').stroke({ color: '#111', width: 1.15 });
  parent.polygon([[x2 - 22, y2 - 33], [x2 + 22, y2 - 33], [x2, y2 + 4]])
    .fill('#f8f8f8').stroke({ color: '#111', width: 1.05 });
}

var layouts = {
  leftD: [[-45,-25,.74,-.35],[-2,-42,.76,.45],[40,-24,.73,-.7],[-44,19,.74,.3],[-2,34,.76,-.55],[39,16,.72,.7]],
  leftM: [],
  midD: [[-48,-25,.66,.1],[38,-27,.64,.75],[-8,31,.63,-.62]],
  midM: [[-50,21,.78,.3],[-6,-6,.8,1.15],[43,15,.78,-.55],[4,-39,.77,2.15],[52,-25,.73,.05]],
  rightD: [[-39,26,.61,.35],[28,29,.61,-.6]],
  rightM: [[-50,-22,.78,-.35],[-7,-28,.78,1.25],[37,-19,.77,.05],[-53,16,.78,.8],[-3,8,.77,-.25],[45,13,.77,-.7],[8,36,.76,.45]]
};

function drawContainer(parent, cx, cy, label, tubeColor, tubeOpacity, key) {
  var g = parent.group();
  addHaloText(g, label, cx, 20, 23, { anchor: 'middle', strokeWidth: 3 });
  drawTestTube(g, cx + 8, 116, tubeColor, -32, tubeOpacity);
  drawCurvedArrow(g, cx + 17, 176, cx, 235);

  var ring = g.circle(156).center(cx, cy).fill('#f9f9f9').stroke({ color: gray, width: 4 });
  ring.on('mousemove', function (e) { showTooltip(label + ': sealed N₂O₄/NO₂ sample at this stage.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup(label, 'Molecules continue reacting in both directions. At equilibrium the mixture looks constant because the forward and reverse reaction rates are equal.');
    })
    .css('cursor', 'pointer');

  var scale = Math.max(0.78, Math.min(1.22, Math.sqrt(state.A0)));
  layouts[key + 'D'].forEach(function (m) { drawN2O4(g, cx + m[0], cy + m[1], m[2] * scale, m[3]); });
  layouts[key + 'M'].forEach(function (m) { drawNO2(g, cx + m[0], cy + m[1], m[2] * scale, m[3]); });
  return g;
}

function drawTopPanel() {
  var top = draw.group();
  drawContainer(top, 110, 315, 't = 0', '#d6d9f0', 0.74, 'left');
  drawContainer(top, 325, 315, 'pre-equilibrium', '#f0cf52', 0.86, 'mid');
  drawContainer(top, 540, 315, 'at equilibrium', '#df7a2e', 0.90, 'right');

  top.line(126, 383, 181, 416).stroke({ color: '#111', width: 4 });
  addHaloText(top, 'N₂O₄', 184, 398, 23, { anchor: 'start', strokeWidth: 4 });
  top.line(315, 377, 370, 415).stroke({ color: '#111', width: 4 });
  addHaloText(top, 'NO₂', 374, 398, 23, { anchor: 'start', strokeWidth: 4 });

  addHaloText(top, '(a)', 325, 442, 23, {});
  addHaloText(top, 'N₂O₄(g) ⇌ 2NO₂(g)', 325, 470, 18, {});
}

function drawAxes(g, ylabel, panelLabel) {
  g.rect(graph.w * (tMax - tEq) / tMax, graph.h)
    .move(tToScreen(tEq), graph.y0 - graph.h)
    .fill(paleYellow).opacity(0.9);
  g.line(tToScreen(tEq), graph.y0 - graph.h, tToScreen(tEq), graph.y0)
    .stroke({ color: '#111', width: 1.55, dasharray: '9 8' });

  g.line(graph.x0, graph.y0, graph.x0, graph.y0 - graph.h - 20).stroke({ color: '#111', width: 2 });
  g.polygon([[graph.x0 - 7, graph.y0 - graph.h - 20], [graph.x0 + 7, graph.y0 - graph.h - 20], [graph.x0, graph.y0 - graph.h - 42]]).fill('#111');
  g.line(graph.x0, graph.y0, graph.x0 + graph.w + 18, graph.y0).stroke({ color: '#111', width: 2 });
  g.polygon([[graph.x0 + graph.w + 18, graph.y0 - 7], [graph.x0 + graph.w + 18, graph.y0 + 7], [graph.x0 + graph.w + 39, graph.y0]]).fill('#111');

  g.line(graph.x0 + 24, graph.y0, graph.x0 + 24, graph.y0 + 19).stroke({ color: '#111', width: 2 });
  addHaloText(g, '0', graph.x0 + 24, graph.y0 + 24, 21, {});
  addHaloText(g, 'Time', graph.x0 + graph.w / 2, graph.y0 + 41, 23, {});
  addHaloText(g, ylabel, graph.x0 - 49, graph.y0 - graph.h / 2 - 28, 23, {}).transform({ rotate: -90, cx: graph.x0 - 49, cy: graph.y0 - graph.h / 2 });
  addHaloText(g, 'Equilibrium\nachieved', tToScreen(7.45), graph.y0 - graph.h * 0.66, 23, {});
  addHaloText(g, panelLabel, 325, graph.y0 + 83, 23, {});
}

function drawMarkerAndReadout(g, maxVal) {
  if (!state.markerVisible) return;
  var markerX = tToScreen(state.t);
  var vals = valuesAt(state.t);

  var marker = g.group();
  marker.line(markerX, graph.y0 - graph.h - 10, markerX, graph.y0 + 7)
    .stroke({ color: '#111', width: 2, dasharray: state.t >= tEq - 0.03 ? 'none' : '5 5' });
  marker.circle(13).center(markerX, graph.y0 - graph.h - 12).fill('#fff').stroke({ color: '#111', width: 1.8 });
  marker.rect(36, graph.h + 40).move(markerX - 18, graph.y0 - graph.h - 30).fill('#000').opacity(0.001);
  marker.on('mousedown', function (e) { draggingMarker = true; updateTimeFromEvent(e); e.preventDefault(); })
    .on('mousemove', function (e) { showTooltip('Drag to sample one time in the same reacting system.', e); })
    .on('mouseleave', hideTooltip)
    .css('cursor', 'ew-resize');

  var dotVal = state.view === 'Concentration' ? vals.no2 : vals.reverse;
  g.circle(10).center(markerX, valToScreen(dotVal, maxVal)).fill(red).stroke({ color: '#fff', width: 2 });

  var boxX = markerX < graph.x0 + graph.w * 0.62 ? markerX + 13 : markerX - 187;
  var boxY = graph.y0 - graph.h - 5;
  g.rect(174, 104).move(boxX, boxY).rx(7).fill('#fff').opacity(0.94).stroke({ color: '#b8b8b8', width: 1 });
  g.text('t = ' + state.t.toFixed(1) +
    '\n[N₂O₄] = ' + vals.n2o4.toFixed(2) +
    '\n[NO₂] = ' + vals.no2.toFixed(2) +
    '\nforward rate = ' + vals.forward.toFixed(2) +
    '\nreverse rate = ' + vals.reverse.toFixed(2))
    .font({ family: 'Arial, Helvetica, sans-serif', size: 14, anchor: 'start' })
    .fill('#111').move(boxX + 9, boxY + 8);
}

function drawGraph() {
  var g = draw.group();
  var maxConc = Math.max(2.55, 1.34 * state.A0);
  var maxRate = Math.max(1.35, 1.1 * Math.pow(state.A0, 0.78));

  if (state.view === 'Concentration') {
    drawAxes(g, 'Concentration', '(b)');
    var blueLine = g.polyline(curvePoints(function (tt) { return valuesAt(tt).n2o4; }, maxConc))
      .fill('none').stroke({ color: blue, width: 5, linecap: 'round', linejoin: 'round' });
    var redLine = g.polyline(curvePoints(function (tt) { return valuesAt(tt).no2; }, maxConc))
      .fill('none').stroke({ color: red, width: 5, linecap: 'round', linejoin: 'round' });
    redLine.on('mousemove', function (e) { showTooltip('[NO₂] rises and then becomes constant after equilibrium is reached.', e); }).on('mouseleave', hideTooltip).css('cursor', 'pointer');
    blueLine.on('mousemove', function (e) { showTooltip('[N₂O₄] falls and then becomes constant after equilibrium is reached.', e); }).on('mouseleave', hideTooltip).css('cursor', 'pointer');
    addHaloText(g, 'NO₂', graph.x0 + 175, graph.y0 - 190, 23, {});
    addHaloText(g, 'N₂O₄', graph.x0 + 175, graph.y0 - 94, 23, {});
    drawMarkerAndReadout(g, maxConc);
  } else {
    drawAxes(g, 'Rate', '(c)');
    var fLine = g.polyline(curvePoints(function (tt) { return valuesAt(tt).forward; }, maxRate))
      .fill('none').stroke({ color: blue, width: 5, linecap: 'round', linejoin: 'round' });
    var rLine = g.polyline(curvePoints(function (tt) { return valuesAt(tt).reverse; }, maxRate))
      .fill('none').stroke({ color: red, width: 5, linecap: 'round', linejoin: 'round' });
    fLine.on('mousemove', function (e) { showTooltip('Forward rate kᶠ[N₂O₄] decreases as N₂O₄ is consumed.', e); }).on('mouseleave', hideTooltip).css('cursor', 'pointer');
    rLine.on('mousemove', function (e) { showTooltip('Reverse rate kᵣ[NO₂]² increases as NO₂ accumulates.', e); }).on('mouseleave', hideTooltip).css('cursor', 'pointer');
    addHaloText(g, 'kᶠ[N₂O₄]', graph.x0 + 70, graph.y0 - 212, 21, { anchor: 'start' });
    addHaloText(g, 'kᵣ[NO₂]²', graph.x0 + 70, graph.y0 - 96, 21, { anchor: 'start' });
    drawMarkerAndReadout(g, maxRate);
  }

  var hot = g.rect(graph.w + 55, graph.h + 55).move(graph.x0, graph.y0 - graph.h - 35).fill('#000').opacity(0.001);
  hot.on('mousedown', function (e) {
      state.markerVisible = true;
      draggingMarker = true;
      updateTimeFromEvent(e);
      e.preventDefault();
    })
    .on('mousemove', function (e) { showTooltip('Drag here to reveal and move the time marker.', e); })
    .on('mouseleave', hideTooltip)
    .css('cursor', 'ew-resize')
    .back();
}

function render() {
  draw.clear();
  draw.rect(650, 900).fill('#fff');
  drawTopPanel();
  drawGraph();
}

function updateTimeFromEvent(e) {
  var rect = document.getElementById('container').getBoundingClientRect();
  var vb = draw.viewbox();
  var sx = vb.width / rect.width;
  var x = (e.clientX - rect.left) * sx + vb.x;
  var t = ((x - graph.x0) / graph.w) * tMax;
  state.t = Math.max(0, Math.min(tMax, t));
  state.markerVisible = true;
  render();
}

document.addEventListener('mousemove', function (e) {
  if (draggingMarker) updateTimeFromEvent(e);
});
document.addEventListener('mouseup', function () { draggingMarker = false; });

function update_initialN2O4(v) {
  state.A0 = v;
  state.markerVisible = true;
  render();
}

