function progressAt(t) {
  if (t >= tEq) return 1;
  var q = Math.max(0, t) / tEq;
  return (1 - Math.exp(-3.8 * q)) / (1 - Math.exp(-3.8));
}

function valuesAt(t) {
  var p = progressAt(t);
  var n2o4 = 0.88 - 0.45 * p;
  var no2 = 0.05 + 0.82 * p;
  var forward = 0.58 + 0.34 * Math.pow(1 - p, 1.25);
  var reverse = 0.58 * Math.pow(p, 1.12);
  if (p >= 1) {
    n2o4 = 0.43;
    no2 = 0.87;
    forward = 0.58;
    reverse = 0.58;
  }
  return { p: p, n2o4: n2o4, no2: no2, forward: forward, reverse: reverse };
}

function graphX(g, t) {
  return g.x0 + t * g.w;
}

function graphY(g, v, maxVal) {
  return g.y0 - (v / maxVal) * g.h;
}

function curvePoints(g, fn, maxVal) {
  var pts = [];
  for (var i = 0; i <= 130; i++) {
    var t = i / 130;
    var v = fn(t);
    pts.push(graphX(g, t).toFixed(1) + ',' + graphY(g, v, maxVal).toFixed(1));
  }
  return pts.join(' ');
}

function addText(parent, txt, x, y, size, opts) {
  opts = opts || {};
  var t = parent.text(txt)
    .font({ family: 'Arial, Helvetica, sans-serif', size: size, anchor: opts.anchor || 'middle', weight: opts.weight || 'normal' })
    .fill(opts.fill || '#000')
    .attr({ 'paint-order': 'stroke', stroke: opts.halo || '#fff', 'stroke-width': opts.strokeWidth == null ? 4 : opts.strokeWidth, 'stroke-linejoin': 'round' });
  if ((opts.anchor || 'middle') === 'start') t.move(x, y - size * 0.55);
  else if ((opts.anchor || 'middle') === 'end') t.move(x, y - size * 0.55);
  else t.center(x, y);
  return t;
}

function addTwoLineText(parent, a, b, x, y, size, opts) {
  opts = opts || {};
  var g = parent.group();
  addText(g, a, x, y - size * 0.55, size, opts);
  addText(g, b, x, y + size * 0.65, size, opts);
  return g;
}

function drawSphere(parent, x, y, r, fill, stroke) {
  parent.circle(2 * r).center(x, y).fill(fill).stroke({ color: stroke || '#777', width: 0.7, opacity: 0.65 });
  parent.circle(r * 0.55).center(x - r * 0.35, y - r * 0.35).fill('#fff').opacity(0.38);
}

function drawNO2(parent, x, y, s, rot) {
  var g = parent.group();
  var a1 = rot == null ? -0.7 : rot;
  var a2 = a1 + 2.25;
  var ox1 = x + Math.cos(a1) * 13 * s;
  var oy1 = y + Math.sin(a1) * 13 * s;
  var ox2 = x + Math.cos(a2) * 13 * s;
  var oy2 = y + Math.sin(a2) * 13 * s;
  g.line(x, y, ox1, oy1).stroke({ color: '#666', width: 2.0 * s, opacity: 0.65 });
  g.line(x, y, ox2, oy2).stroke({ color: '#666', width: 2.0 * s, opacity: 0.65 });
  drawSphere(g, ox1, oy1, 7.7 * s, '#ee202b', '#9b1118');
  drawSphere(g, ox2, oy2, 7.7 * s, '#ee202b', '#9b1118');
  drawSphere(g, x, y, 6.8 * s, '#4269b1', '#263f83');
  g.on('mousemove', function (e) { showTooltip('NO₂: one nitrogen atom bonded to two oxygen atoms; brown gas.', e); })
    .on('mouseleave', hideTooltip)
    .css('cursor', 'pointer');
  return g;
}

function drawN2O4(parent, x, y, s, rot) {
  var g = parent.group();
  var a = rot == null ? 0.25 : rot;
  var dx = Math.cos(a) * 10.8 * s;
  var dy = Math.sin(a) * 10.8 * s;
  g.line(x - dx, y - dy, x + dx, y + dy).stroke({ color: '#565656', width: 2.6 * s, opacity: 0.78 });
  drawNO2(g, x - dx, y - dy, s * 0.92, a + 2.42);
  drawNO2(g, x + dx, y + dy, s * 0.92, a - 0.73);
  g.on('mousemove', function (e) { showTooltip('N₂O₄: two joined NO₂ units; mostly colorless.', e); })
    .on('mouseleave', hideTooltip)
    .css('cursor', 'pointer');
  return g;
}

function drawTestTube(parent, cx, cy, color, angle, opacity) {
  var g = parent.group();
  g.transform({ rotate: angle, cx: cx, cy: cy });
  g.line(cx, cy - 74, cx, cy + 45).stroke({ color: '#84889f', width: 27, linecap: 'round', opacity: 0.28 });
  g.line(cx, cy - 69, cx, cy + 40).stroke({ color: color, width: 20, linecap: 'round', opacity: opacity });
  g.line(cx - 7, cy - 62, cx - 7, cy + 23).stroke({ color: '#fff', width: 3.2, linecap: 'round', opacity: 0.45 });
  g.line(cx, cy - 74, cx, cy + 45).stroke({ color: '#6e748e', width: 1.15, linecap: 'round', opacity: 0.42 });
  return g;
}

function drawDownArrow(parent, x, y1, y2) {
  parent.path('M' + x + ' ' + y1 + ' C ' + (x - 35) + ' ' + (y1 + 30) + ', ' + (x - 36) + ' ' + (y2 - 50) + ', ' + x + ' ' + y2)
    .fill('none').stroke({ color: '#111', width: 1.5 });
  parent.polygon([[x - 23, y2 - 39], [x + 23, y2 - 39], [x, y2 + 2]])
    .fill('#f8f8f8').stroke({ color: '#111', width: 1.2 });
}

var moleculeLayouts = {
  leftD: [[-45,-24,.75,-.4],[-5,-42,.74,.25],[39,-24,.73,-.75],[-48,17,.75,.35],[-3,27,.76,-.55],[39,16,.73,.7],[0,55,.74,.0]],
  leftM: [],
  midD: [[-50,-24,.66,.15],[35,-25,.64,.75],[-4,36,.63,-.65]],
  midM: [[-53,17,.78,.35],[-13,-3,.79,1.15],[43,11,.78,-.55],[8,-43,.76,2.15],[57,-25,.72,.05],[-40,48,.74,-.2]],
  rightD: [[-39,27,.61,.35],[26,31,.61,-.6]],
  rightM: [[-52,-23,.78,-.35],[-10,-29,.78,1.25],[35,-20,.77,.05],[-54,16,.78,.8],[-4,8,.77,-.25],[46,14,.77,-.7],[7,38,.76,.45],[-35,47,.73,.25]]
};

function drawContainer(parent, cx, cy, label, tubeColor, tubeOpacity, key, selected) {
  var g = parent.group();
  addText(g, label, cx, 30, 27, { strokeWidth: 3 });
  drawTestTube(g, cx + 4, 112, tubeColor, -34, tubeOpacity);
  drawDownArrow(g, cx + 8, 172, 222);

  var ring = g.circle(150).center(cx, cy).fill('#fbfbfb').stroke({ color: gray, width: 4 });
  if (selected) {
    g.circle(164).center(cx, cy).fill('none').stroke({ color: '#2a9d55', width: 4, opacity: 0.75, dasharray: '8 6' });
  }
  ring.on('mousemove', function (e) { showTooltip(label + ': one molecular snapshot of the same reversible reaction mixture.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
