    })
    .css('cursor', 'pointer');

  moleculeLayouts[key + 'D'].forEach(function (m) { drawN2O4(g, cx + m[0], cy + m[1], m[2], m[3]); });
  moleculeLayouts[key + 'M'].forEach(function (m) { drawNO2(g, cx + m[0], cy + m[1], m[2], m[3]); });
  return g;
}

function selectedSnapshot() {
  if (state.time < 0.22) return 'left';
  if (state.time < tEq) return 'mid';
  return 'right';
}

function drawTopPanel() {
  var top = draw.group();
  var sel = selectedSnapshot();
  drawContainer(top, 165, 275, 't = 0', '#d9dbf1', 0.78, 'left', sel === 'left');
  drawContainer(top, 450, 275, 'pre-equilibrium', '#efc85c', 0.88, 'mid', sel === 'mid');
  drawContainer(top, 735, 275, 'at equilibrium', orange, 0.92, 'right', sel === 'right');

  top.line(210, 324, 258, 365).stroke({ color: '#111', width: 4 });
  addText(top, 'N₂O₄', 262, 366, 29, { anchor: 'start', strokeWidth: 5 });

  top.line(493, 320, 538, 365).stroke({ color: '#111', width: 4 });
  addText(top, 'NO₂', 544, 366, 29, { anchor: 'start', strokeWidth: 5 });

  addText(top, '(a)', 450, 430, 27, { strokeWidth: 3 });
  addText(top, 'N₂O₄(g) ⇌ 2NO₂(g)', 450, 462, 22, { strokeWidth: 3 });
}

function drawAxisArrow(parent, x1, y1, x2, y2, direction) {
  parent.line(x1, y1, x2, y2).stroke({ color: '#111', width: 2.4 });
  if (direction === 'x') {
    parent.polygon([[x2, y2 - 8], [x2, y2 + 8], [x2 + 25, y2]]).fill('#111');
  } else {
    parent.polygon([[x2 - 8, y2], [x2 + 8, y2], [x2, y2 - 25]]).fill('#111');
  }
}

function drawAxes(g, spec, ylabel) {
  g.rect(spec.w * (1 - tEq), spec.h)
    .move(graphX(spec, tEq), spec.y0 - spec.h)
    .fill(paleYellow).opacity(0.94);

  g.line(graphX(spec, tEq), spec.y0 - spec.h, graphX(spec, tEq), spec.y0)
    .stroke({ color: '#111', width: 1.8, dasharray: '10 9' });

  drawAxisArrow(g, spec.x0, spec.y0, spec.x0 + spec.w + 25, spec.y0, 'x');
  drawAxisArrow(g, spec.x0, spec.y0, spec.x0, spec.y0 - spec.h - 15, 'y');

  g.line(spec.x0, spec.y0 - 9, spec.x0, spec.y0 + 18).stroke({ color: '#111', width: 2.2 });
  addText(g, '0', spec.x0, spec.y0 + 36, 23, { strokeWidth: 3 });
  addText(g, 'Time', spec.x0 + spec.w / 2, spec.y0 + 42, 25, { strokeWidth: 3 });

  var yt = addText(g, ylabel, spec.x0 - 58, spec.y0 - spec.h / 2, 25, { strokeWidth: 4 });
  yt.transform({ rotate: -90, cx: spec.x0 - 58, cy: spec.y0 - spec.h / 2 });

  addTwoLineText(g, 'Equilibrium', 'achieved', graphX(spec, 0.82), spec.y0 - spec.h * 0.58, 24, { strokeWidth: 4 });
