  var vals = valuesAt(state.time);
  g.line(x, spec.y0 - spec.h - 10, x, spec.y0 + 6)
    .stroke({ color: '#222', width: 2, dasharray: '5 5' });
  g.circle(10).center(x, spec.y0 - spec.h - 12).fill('#fff').stroke({ color: '#222', width: 1.6 });

  if (kind === 'conc') {
    g.circle(9).center(x, graphY(spec, vals.n2o4, maxVal)).fill(blue).stroke({ color: '#fff', width: 2 });
    g.circle(9).center(x, graphY(spec, vals.no2, maxVal)).fill(red).stroke({ color: '#fff', width: 2 });
  } else {
    g.circle(9).center(x, graphY(spec, vals.forward, maxVal)).fill(blue).stroke({ color: '#fff', width: 2 });
    g.circle(9).center(x, graphY(spec, vals.reverse, maxVal)).fill(red).stroke({ color: '#fff', width: 2 });
  }
}

function graphOpacity(which) {
  if (state.emphasis === 'Show both panels' || state.emphasis === 'Link both') return 1;
  if (state.emphasis === which) return 1;
  return 0.5;
}

function drawEmphasisFrame(spec, which) {
  if (state.emphasis === which || state.emphasis === 'Link both') {
    draw.rect(spec.w + 120, spec.h + 128)
      .move(spec.x0 - 82, spec.y0 - spec.h - 42)
      .fill('none')
      .stroke({ color: state.emphasis === 'Link both' ? '#2a9d55' : '#111', width: 3, dasharray: state.emphasis === 'Link both' ? '9 7' : 'none' })
      .radius(8)
      .opacity(0.8);
  }
}

function addGraphHitArea(g, spec) {
  g.rect(spec.w + 45, spec.h + 55).move(spec.x0, spec.y0 - spec.h - 25)
    .fill('#000').opacity(0.001)
    .on('mousedown', function (e) {
      dragging = true;
      updateTimeFromEvent(e);
      e.preventDefault();
    })
    .on('mousemove', function (e) { showTooltip('Drag horizontally to read both graphs at the same time.', e); })
    .on('mouseleave', hideTooltip)
    .css('cursor', 'ew-resize')
    .back();
}

function drawConcentrationGraph() {
  var spec = concGraph;
  drawEmphasisFrame(spec, 'Concentration panel');
  var g = draw.group().opacity(graphOpacity('Concentration panel'));
  addGraphHitArea(g, spec);
  drawAxes(g, spec, 'Concentration');

  var blueLine = g.polyline(curvePoints(spec, function (t) { return valuesAt(t).n2o4; }, 1.02))
    .fill('none').stroke({ color: blue, width: 5, linecap: 'round', linejoin: 'round' });
  var redLine = g.polyline(curvePoints(spec, function (t) { return valuesAt(t).no2; }, 1.02))
    .fill('none').stroke({ color: red, width: 5, linecap: 'round', linejoin: 'round' });

  redLine.on('mousemove', function (e) { showTooltip('[NO₂] rises, then becomes constant once equilibrium is achieved.', e); }).on('mouseleave', hideTooltip).css('cursor', 'pointer');
  blueLine.on('mousemove', function (e) { showTooltip('[N₂O₄] falls, then becomes constant once equilibrium is achieved.', e); }).on('mouseleave', hideTooltip).css('cursor', 'pointer');

  addText(g, 'NO₂', spec.x0 + 128, spec.y0 - 175, 25, { fill: '#000', strokeWidth: 4 });
  addText(g, 'N₂O₄', spec.x0 + 132, spec.y0 - 86, 25, { fill: '#000', strokeWidth: 4 });
  drawMarker(g, spec, 1.02, 'conc');
}

function drawRateGraph() {
  var spec = rateGraph;
  drawEmphasisFrame(spec, 'Rate panel');
  var g = draw.group().opacity(graphOpacity('Rate panel'));
  addGraphHitArea(g, spec);
  drawAxes(g, spec, 'Rate');

  var fLine = g.polyline(curvePoints(spec, function (t) { return valuesAt(t).forward; }, 1.0))
    .fill('none').stroke({ color: blue, width: 5, linecap: 'round', linejoin: 'round' });
  var rLine = g.polyline(curvePoints(spec, function (t) { return valuesAt(t).reverse; }, 1.0))
    .fill('none').stroke({ color: red, width: 5, linecap: 'round', linejoin: 'round' });

  fLine.on('mousemove', function (e) { showTooltip('Forward rate kf[N₂O₄] decreases as N₂O₄ is consumed.', e); }).on('mouseleave', hideTooltip).css('cursor', 'pointer');
  rLine.on('mousemove', function (e) { showTooltip('Reverse rate kr[NO₂]² increases as NO₂ accumulates.', e); }).on('mouseleave', hideTooltip).css('cursor', 'pointer');

  addText(g, 'kᶠ[N₂O₄]', spec.x0 + 45, spec.y0 - 184, 22, { anchor: 'start', strokeWidth: 4 });
  addText(g, 'kᵣ[NO₂]²', spec.x0 + 45, spec.y0 - 73, 22, { anchor: 'start', strokeWidth: 4 });
  drawMarker(g, spec, 1.0, 'rate');
}

function drawReadout() {
  var vals = valuesAt(state.time);
  var afterEq = state.time >= tEq;
  var status = afterEq ? 'equilibrium: equal ongoing rates' : 'approaching equilibrium';
  var g = draw.group();
  g.rect(430, 70).move(235, 493).rx(8).fill('#fff').opacity(0.96).stroke({ color: '#bfc3c7', width: 1.2 });
  addText(g, 'selected time = ' + state.time.toFixed(2) + '  •  ' + status, 450, 510, 16, { strokeWidth: 2 });
  addText(g, '[N₂O₄] ' + vals.n2o4.toFixed(2) + '   [NO₂] ' + vals.no2.toFixed(2), 450, 532, 16, { strokeWidth: 2 });
  addText(g, 'forward rate ' + vals.forward.toFixed(2) + '   reverse rate ' + vals.reverse.toFixed(2), 450, 554, 16, { strokeWidth: 2 });
  g.on('mousemove', function (e) { showTooltip('The same selected time is marked on both graphs, linking concentration change to rate equality.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Dynamic equilibrium', 'Constant concentrations do not mean the reaction stopped. They mean NO₂ is being produced and consumed at equal nonzero rates.');
    })
    .css('cursor', 'pointer');
}

function render() {
  draw.clear();
  draw.rect(900, 980).fill('#fff');
  drawTopPanel();
  drawReadout();
  drawConcentrationGraph();
  drawRateGraph();

  if (state.emphasis === 'Link both') {
    var x1 = graphX(concGraph, state.time);
    var x2 = graphX(rateGraph, state.time);
    draw.line(x1, 575, x1, 600).stroke({ color: '#2a9d55', width: 2, dasharray: '5 5' });
    draw.line(x2, 575, x2, 600).stroke({ color: '#2a9d55', width: 2, dasharray: '5 5' });
    draw.line(x1, 588, x2, 588).stroke({ color: '#2a9d55', width: 2, dasharray: '6 6' });
    addText(draw, 'same time in both panels', 450, 585, 15, { fill: '#2a6f3f', strokeWidth: 3 });
  }
}

function updateTimeFromEvent(e) {
  var rect = document.getElementById('container').getBoundingClientRect();
  var vb = draw.viewbox();
  var sx = vb.width / rect.width;
  var sy = vb.height / rect.height;
  var x = (e.clientX - rect.left) * sx + vb.x;
  var y = (e.clientY - rect.top) * sy + vb.y;
  var spec = Math.abs(x - (rateGraph.x0 + rateGraph.w / 2)) < Math.abs(x - (concGraph.x0 + concGraph.w / 2)) ? rateGraph : concGraph;
  if (y < 560 || y > 880) return;
  state.time = Math.max(0, Math.min(1, (x - spec.x0) / spec.w));
  document.getElementById('timePointInput').value = state.time.toFixed(2);
  document.getElementById('timePointVal').value = state.time.toFixed(2);
  render();
}

document.addEventListener('mousemove', function (e) {
  if (dragging) updateTimeFromEvent(e);
});
document.addEventListener('mouseup', function () { dragging = false; });

function update_timePoint(v) {
  state.time = Math.max(0, Math.min(1, v));
  render();
}

function update_panelEmphasis(v) {
  state.emphasis = v;
  render();
}

function applyStep(i) {
  state.step = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[state.step];
  state.time = s.state.timePoint;
  state.emphasis = s.state.panelEmphasis;
  document.getElementById('timePointInput').value = state.time;
  document.getElementById('timePointVal').value = state.time;
  document.getElementById('panelEmphasisInput').value = state.emphasis;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (state.step + 1) + '/' + steps.length + ' ' + s.title;
  render();
}

function prevStep() { applyStep(state.step - 1); }
function nextStep() { applyStep(state.step + 1); }

window.update_timePoint = update_timePoint;
window.update_panelEmphasis = update_panelEmphasis;
window.prevStep = prevStep;
window.nextStep = nextStep;

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

